// Filtra os emails que ainda não receberam a newsletter atual
// e remover os que contêm 'anonimo'

const newsAtual = parseInt($items("Aprovada", 0, 0)[0].json.query.id, 10);
const rows = $items("Get row(s) in sheet1", 0, 0).map(i => i.json);

const filtrados = rows.filter(row => {
  const enviado = parseInt(row["news enviada"], 10) || 0;
  const email = (row.email || "").toLowerCase();
  return enviado < newsAtual && !email.includes("anonimo");
});

// Retorna preservando o row_number
return filtrados.map(r => ({
  json: {
    ...r,
    row_number: r.row_number   // garante que o update saiba qual linha alterar
  }
}));

// Node: Remover bloco de orientações/aprovação do HTML final

// Pega o HTML vindo do node anterior
const html = $json.html || "";

// Remove o bloco <tr> que contém "Orientações:" até o fechamento </tr>
const cleanedHtml = html.replace(
  /<tr>\s*<td[^>]*>\s*<h3>Orientações:[\s\S]*?<\/tr>/i,
  ""
);

// Retorna o HTML limpo
return [{ json: { html: cleanedHtml } }];

// Node: Ajustar ID do botão APROVADA (regex seguro)

// Pega o HTML vindo do AI Agent ou da Data Table Insert
let html = $json.output || $json.html || "";

// Pega o ID recém-criado na Data Table
const newsId = $json.id;

// Se não houver ID, apenas retorna sem erro
if (!newsId) {
  return [{ json: { html, warning: "ID da newsletter não encontrado" } }];
}

// 1. Atualiza o número do botão APROVADA
html = html.replace(/(id=)\d+/, `$1${newsId}`);

// 2. Atualiza também o número dentro do <strong> (texto do ID da newsletter)
html = html.replace(/(<strong>)\d+(<\/strong>)/, `$1${newsId}$2`);

// Retorna o HTML ajustado junto com o ID
return [{ json: { html, id: newsId } }];

