// Recebe o array enviado pelo formulário
const selections = $json.body || [];

// Filtra apenas os itens que têm prioridade definida
const comPrioridade = selections.filter(item => {
  return item.priority && item.priority.toUpperCase() !== "X";
});

// Ordena por prioridade numérica
const ordenados = comPrioridade.sort((a, b) => {
  return parseInt(a.priority) - parseInt(b.priority);
});

// Retorna cada item como uma execução separada
return ordenados.map(item => ({ json: item }));

