// Filtra os emails que ainda não receberam a newsletter atual
// e remover os que contêm 'anonimo'

const newsAtual = parseInt($items("Aprovada", 0, 0)[0].json.query.id, 10);
const rows = $items("Get row(s) in sheet1", 0, 0).map(i => i.json);

const filtrados = rows.filter(row => {
  const enviado = parseInt(row["news enviada"], 10) || 0;
  const email = (row.email || "").toLowerCase();
  return enviado < newsAtual && !email.includes("anonimo");
});

// Retorna preservando o row_number
return filtrados.map(r => ({
  json: {
    ...r,
    row_number: r.row_number   // garante que o update saiba qual linha alterar
  }
}));

// Node: Remover bloco de orientações/aprovação do HTML final

const html = $json.html || "";

// Remove tudo a partir de "Orientações para o gestor da newsletter" até o fim
const cleanedHtml = html.replace(
  /Orientações para o gestor da newsletter[\s\S]*$/i,
  ""
);

return [{ json: { html: cleanedHtml } }];

// Node: Ajustar ID do botão APROVADA (regex seguro)

// Pega o HTML vindo do AI Agent ou da Data Table Insert
let html = $json.html || $json.output || "";

// Pega o ID recém-criado na Data Table
const newsId = $json.id;

// Se não houver ID, apenas retorna sem erro
if (!newsId) {
  return [{ json: { html, warning: "ID da newsletter não encontrado" } }];
}

// 1. Atualiza o número do botão APROVADA
html = html.replace(/(id=)\d+/, `$1${newsId}`);

// 2. Atualiza também o número dentro do <strong> (texto do ID da newsletter)
html = html.replace(/(<strong>)\d+(<\/strong>)/, `$1${newsId}$2`);

// Retorna o HTML ajustado junto com o ID
return [{ json: { html, id: newsId } }];

// Node: Segregar descartados e preparar output para Update rows

const body = $json.body || {};
const updates = [];

for (const [key, value] of Object.entries(body)) {
  if (key.startsWith("priority_") && value.toLowerCase() === "x") {
    const id = key.replace("priority_", "");
    updates.push({
      json: {
        id,            // ID da linha na Data Table
        status: "descartado" // campo que você quer atualizar
      }
    });
  }
}

return updates;

// Node: Coleta priorizados
// Lê o body do Webhook e retorna itens com prioridade numérica (não vazio, não "x")
const body = $json.body || {};
const priorizados = [];

for (const [key, value] of Object.entries(body)) {
  if (!key.startsWith('priority_')) continue;
  const raw = String(value || '').trim().toLowerCase();

  // Ignora vazios e "x"
  if (!raw || raw === 'x') continue;

  // Considera apenas números válidos
  const n = Number(raw);
  if (!Number.isFinite(n)) continue;

  const id = key.replace('priority_', '');
  priorizados.push({ json: { id, priority: n } });
}

// Ordena pela prioridade crescente (1 primeiro, 2 depois...)
priorizados.sort((a, b) => a.json.priority - b.json.priority);

return priorizados;

const email = $json.body?.email || null;
if (!email) {
  throw new Error('Email não informado no link de descadastro.');
}
return [{ json: { email } }];

// Gera URL pública do S3 usando pasta fixa "Kutsaca"

const items = $input.all();

return items.map(item => {
  const region = 'us-east-1';
  const bucket = 'auto.1mc.co';
  const folder = 'Midiacode';

  // filename vindo do formulário
  const filename = item.json['Faça upload de uma imagem para essa notícia (opcional)']?.filename;

  if (!filename) {
    throw new Error('Nenhum filename encontrado no formulário.');
  }

  // S3 usa + no lugar de espaço
  const encoded = encodeURIComponent(filename).replace(/%20/g, '+');

  // Monta a URL pública com a pasta
  const imageUrl = `https://s3.${region}.amazonaws.com/${bucket}/${folder}/${encoded}`;

  return {
    json: {
      imageUrl,
      filename,
      uploadedAt: new Date().toISOString()
    }
  };
});

// Unifica:
// 1. Extração dos parâmetros do Form Trigger
// 2. Preservação do binário
// 3. Geração da URL pública do S3 sem depender do retorno do S3
// -------------------------------------------------------

//
// 1. Extrai parâmetros do formulário
//
const q = $json.formQueryParameters || {};

function decode(value) {
  if (!value) return "";
  try {
    return decodeURIComponent(value);
  } catch (e) {
    return value;
  }
}

//
// 2. Gera o nome do arquivo manualmente
//
const original = $binary.nova_imagem.fileName;

// S3 usa encoding + substituição de espaços
const encoded = encodeURIComponent(original).replace(/%20/g, '+');

//
// 3. Monta URL pública no padrão do editor
//
const region = 'us-east-1';
const bucket = 'auto.1mc.co';
const folder = 'Kutsaca';

const finalUrl = `https://s3.${region}.amazonaws.com/${bucket}/${folder}/${encoded}`;

//
// 4. Retorna tudo pronto para o DataTable
//
return [
