function normalizeDriveLink(link) {
  if (!link) return null;

  // Caso seja link no formato "file/d/ID/view"
  const matchFile = link.match(/\/file\/d\/([^/]+)\//);
  if (matchFile) {
    return `https://drive.google.com/uc?id=${matchFile[1]}&export=view`;
  }

  // Caso seja link no formato "uc?id=ID&export=download"
  const matchUc = link.match(/uc\?id=([^&]+)/);
  if (matchUc) {
    return `https://drive.google.com/uc?id=${matchUc[1]}&export=view`;
  }

  // Se não bater nenhum padrão, retorna original
  return link;
}

