/********************************************************************
 * NODE: monta o html a partir do get rows
 * Funciona tanto:
 *  - na primeira geração da página (sem body)
 *  - quanto no retorno da edição (com body)
 ********************************************************************/

// Notícias vindas do DataTable (primeiro fluxo usa "Get row(s)")
const items = $items("Get row(s)", 0, 0);

// Tenta pegar o body do Webhook1 (se existir no fluxo de edição)
let webhookItem;
try {
  webhookItem = $items("Webhook1", 0, 0);
} catch (e) {
  webhookItem = null;
}

// Se não existir Webhook1 → body vazio
const body = webhookItem?.json?.body || {};

// Campos adicionais
const titulo_newsletter = body.titulo_newsletter || "";
const saudacao = body.saudacao || "";
const finalizacao = body.finalizacao || "";

// Função para preencher prioridades
function getPriority(id) {
  return body[`priority_${id}`] || "";
}

// Corrige links de imagem
function fixImageLink(link) {
  if (!link) return null;
  return link.replace("download", "view");
}

// INÍCIO DO HTML
let html = `<!DOCTYPE html>
<html lang="pt-BR">
<head>
  <meta charset="UTF-8">
  <title>Seleção de Notícias para Newsletter</title>

  <style>
    body { margin:0; padding:0; font-family:Arial; background:#f4f4f4; }
    .container { padding:30px; max-width:1200px; margin:auto; }
    .card { background:#fff; border:1px solid #ccc; padding:15px; border-radius:6px; margin-bottom:20px; }
    textarea, input[type="text"] {
      width:100%; padding:10px; border:1px solid #ccc; border-radius:4px;
      font-size:14px; box-sizing:border-box;
    }
  </style>

</head>
<body>

<div class="container">

  <h2 style="color:#e74c3c;text-align:center;margin-bottom:20px;">
    Seleção de Notícias para Newsletter
  </h2>

  <div class="card">
    <p><strong>Instruções:</strong></p>
    <ul>
      <li>Insira um número de prioridade para cada notícia.</li>
      <li>Campos em branco não serão usados.</li>
      <li>Para excluir uma notícia, insira X.</li>
      <li>Use números para definir a ordem.</li>
    </ul>
  </div>

  <!-- FORM PRINCIPAL -->
  <form action="https://n8n.ooniverse.ai/webhook/d3dd1153-368e-46fb-9951-65a568a15ad7" method="POST">
`;

// LOOP DAS NOTÍCIAS
for (const item of items) {
  const id = item.json.id;
  const imgLink = fixImageLink(item.json.imagens || "");
  const videoLink = item.json.video || null;

  html += `
    <div class="card">

      <div style="display:flex;justify-content:space-between;align-items:center;">
        <p style="margin:0;font-weight:bold;">ID: ${id}</p>

        <!-- Botão de edição -->
        <button type="button"
                onclick="submitEdit(${id})"
                style="background:none;border:none;font-size:18px;cursor:pointer;">
          ✏️
        </button>
      </div>

      <h3>${item.json.titulo}</h3>
      <p>${item.json.text}</p>

      <p><strong>Imagem:</strong> ${
        imgLink ? `<a href="${imgLink}" target="_blank">${imgLink}</a>` : "<em>SEM IMAGEM</em>"
      }</p>

      <p><strong>Vídeo:</strong> ${
        videoLink ? `<a href="${videoLink}" target="_blank">${videoLink}</a>` : "<em>SEM VIDEO</em>"
      }</p>

      <label><strong>Prioridade:</strong></label>
      <input type="text"
             name="priority_${id}"
             value="${getPriority(id)}"
             placeholder="Número ou X"
             maxlength="2">
    </div>
  `;
}

// CAMPOS ADICIONAIS
html += `
    <div class="card" style="background:#f4f4f4;">
      <h3>Textos adicionais</h3>

      <label><strong>Título da Newsletter:</strong></label>
      <input type="text" name="titulo_newsletter" value="${titulo_newsletter}" placeholder="Digite o título...">

      <label><strong>Saudação:</strong></label>
      <textarea name="saudacao">${saudacao}</textarea>

      <label><strong>Finalização:</strong></label>
      <textarea name="finalizacao">${finalizacao}</textarea>
    </div>

    <button type="submit"
            style="background:#e74c3c;color:#fff;padding:14px;border:none;border-radius:6px;font-size:16px;width:100%;cursor:pointer;">
      Salvar Seleção
    </button>

  </form>
</div>

<!-- SCRIPT DE EDIÇÃO (AGORA NO FINAL DO BODY, CORRETO) -->
<script>
  function submitEdit(id) {
    const form = document.createElement("form");
    form.method = "POST";
    form.action = "https://n8n.ooniverse.ai/webhook/edit-news";

    function add(name, value) {
      const input = document.createElement("input");
      input.type = "hidden";
      input.name = name;
      input.value = value;
      form.appendChild(input);
    }

    add("titulo_newsletter", document.querySelector("[name='titulo_newsletter']").value);
    add("saudacao", document.querySelector("[name='saudacao']").value);
    add("finalizacao", document.querySelector("[name='finalizacao']").value);

    document.querySelectorAll("input[name^='priority_']").forEach(el => {
      add(el.name, el.value);
    });

    add("id", id);

    document.body.appendChild(form);
    form.submit();
  }
</script>

</body>
</html>
`;

return [{ json: { html } }];

// Node: Montar lista de notícias selecionadas

// 1. IDs ordenados vindos do node "Limpa o webhook só com prioridades"
const selections = $items("Coleta priorizados", 0, 0).map(i => i.json);

// 2. Todas as notícias vindas do node "Get row(s)1"
const allNews = $items("Get row(s)1", 0, 0).map(i => i.json);

// 3. Monta lista final na ordem da prioridade
const result = [];

for (const sel of selections) {
  const news = allNews.find(n => n.id == sel.id);
  if (news) {
    result.push({
      json: {
        id: sel.id,
        priority: sel.priority,
        titulo: news.titulo,
        text: news.text,
        imagem: news.imagens || null,
        video: news.video || null
      }
    });
  }
}

return result;

// Node: Normaliza links de imagem do Google Drive

function normalizeDriveLink(link) {
  if (!link) return null;

  // Caso seja link no formato "file/d/ID/view"
  const matchFile = link.match(/\/file\/d\/([^/]+)\//);
  if (matchFile) {
    return `https://drive.google.com/uc?id=${matchFile[1]}&export=view`;
  }

  // Caso seja link no formato "uc?id=ID&export=download"
  const matchUc = link.match(/uc\?id=([^&]+)/);
  if (matchUc) {
    return `https://drive.google.com/uc?id=${matchUc[1]}&export=view`;
  }

  // Se não bater nenhum padrão, retorna original
  return link;
}

const items = $items("Filtra do getRows só o priorizado", 0, 0).map(i => i.json);

const result = items.map(item => {
  return {
    json: {
      id: item.id,
      priority: item.priority,
      titulo: item.titulo,
      text: item.text,
      imagem: normalizeDriveLink(item.imagem),
      video: item.video
    }
  };
});

return result;

const html = $json.html || "";
const cleanedHtml = html.replace(
  /Orientações para o gestor[\s\S]*$/i,
  ""
);

return [{
  json: {
    ...$json,   // <— preserva tudo
    html: cleanedHtml
  }
}];

// Node: Ajustar ID do botão APROVADA (regex seguro)

// Pega o HTML vindo do AI Agent ou da Data Table Insert
let html = $json.html || $json.output || "";

// Pega o ID recém-criado na Data Table
const newsId = $json.id;

// Se não houver ID, apenas retorna sem erro
if (!newsId) {
  return [{ json: { html, warning: "ID da newsletter não encontrado" } }];
}

// 1. Atualiza o número do botão APROVADA
html = html.replace(/(id=)\d+/, `$1${newsId}`);

// 2. Atualiza também o número dentro do <strong> (texto do ID da newsletter)
html = html.replace(/(<strong>)\d+(<\/strong>)/, `$1${newsId}$2`);

// Retorna o HTML ajustado junto com o ID
return [{ json: { html, id: newsId } }];

