const priorizados = [];

for (const [key, value] of Object.entries(body)) {
  if (!key.startsWith('priority_')) continue;
  const raw = String(value || '').trim().toLowerCase();

  // Ignora vazios e "x"
  if (!raw || raw === 'x') continue;

  // Considera apenas números válidos
  const n = Number(raw);
  if (!Number.isFinite(n)) continue;

  const id = key.replace('priority_', '');
  priorizados.push({ json: { id, priority: n } });
}

// Ordena pela prioridade crescente (1 primeiro, 2 depois...)
priorizados.sort((a, b) => a.json.priority - b.json.priority);

return priorizados;

const email = $json.body?.email || null;
if (!email) {
  throw new Error('Email não informado no link de descadastro.');
}
return [{ json: { email } }];

