</div>

<!-- SCRIPT DE EDIÇÃO (NO FINAL DO BODY — CORRETO) -->
<script>
  function submitEdit(id) {
    const form = document.createElement("form");
    form.method = "POST";
    form.action = "https://n8n.ooniverse.ai/webhook/edit-news";

    function add(name, value) {
      const input = document.createElement("input");
      input.type = "hidden";
      input.name = name;
      input.value = value;
      form.appendChild(input);
    }

    add("titulo_newsletter", document.querySelector("[name='titulo_newsletter']").value);
    add("saudacao", document.querySelector("[name='saudacao']").value);
    add("finalizacao", document.querySelector("[name='finalizacao']").value);

    document.querySelectorAll("input[name^='priority_']").forEach(el => {
