// Gera URL pública do S3 usando pasta fixa "Kutsaca"

const items = $input.all();

return items.map(item => {
  const region = 'us-east-1';
  const bucket = 'auto.1mc.co';
  const folder = 'Kutsaca';

  // filename vindo do formulário
  const filename = item.json['Faça upload de uma imagem para essa notícia (opcional)']?.filename;

  if (!filename) {
    throw new Error('Nenhum filename encontrado no formulário.');
  }

  // S3 usa + no lugar de espaço
  const encoded = encodeURIComponent(filename).replace(/%20/g, '+');

  // Monta a URL pública com a pasta
  const imageUrl = `https://s3.${region}.amazonaws.com/${bucket}/${folder}/${encoded}`;

  return {
    json: {
      imageUrl,
      filename,
      uploadedAt: new Date().toISOString()
    }
  };
});

// Unifica:
// 1. Extração dos parâmetros do Form Trigger
// 2. Preservação do binário
// 3. Geração da URL pública do S3 sem depender do retorno do S3
// -------------------------------------------------------

//
// 1. Extrai parâmetros do formulário
//
const q = $json.formQueryParameters || {};

function decode(value) {
  if (!value) return "";
  try {
    return decodeURIComponent(value);
  } catch (e) {
    return value;
  }
}

//
// 2. Gera o nome do arquivo manualmente
//
const original = $binary.nova_imagem.fileName;

// S3 usa encoding + substituição de espaços
const encoded = encodeURIComponent(original).replace(/%20/g, '+');

//
// 3. Monta URL pública no padrão do editor
//
const region = 'us-east-1';
const bucket = 'auto.1mc.co';
const folder = 'Kutsaca';

const finalUrl = `https://s3.${region}.amazonaws.com/${bucket}/${folder}/${encoded}`;

//
// 4. Retorna tudo pronto para o DataTable
//
return [
  {
    json: {
      id: Number(q.id) || null,
      titulo: decode(q.titulo),
      text: decode(q.text),
      video: decode(q.video),
      novaImagem: finalUrl
    },
    binary: {
      nova_imagem: $binary.nova_imagem
    }
  }
];

return [
  {
    json: {
      redirect: `https://n8n.ooniverse.ai/webhook/edit-news?id=${$json.id}`
    }
  }
];

// ------------------------------------------------------------
// Node: Normaliza e HTML
// Gera o formulário de edição com editor Quill (texto formatado)
// ------------------------------------------------------------

// Dados vindos do DataTable
const item = $json;

// Normalização
const id = item.id;
const titulo = item.titulo || "";
const text = item.text || "";
const video = item.video || "";
const imagens = item.imagens || "";

// Função para escapar aspas dentro de atributos HTML
function esc(v) {
  return (v || "").replace(/"/g, '&quot;');
}

// ------------------------------------------------------------
// HTML COMPLETO COM EDITOR QUILL
// ------------------------------------------------------------
const html = `
<!DOCTYPE html>
<html lang="pt">
<head>
  <meta charset="UTF-8">
  <title>Editar notícia</title>

  <!-- CSS do Quill -->
  <link href="https://cdn.jsdelivr.net/npm/quill@2.0.3/dist/quill.snow.css" rel="stylesheet">

  <style>
    body {
      font-family: 'Open Sans', sans-serif;
      background: #fbfcfe;
      margin: 0;
      padding: 40px;
      display: flex;
      justify-content: center;
    }
    .card {
      background: #ffffff;
      border: 1px solid #dbdfe7;
      border-radius: 8px;
      box-shadow: 0px 4px 16px rgba(99, 77, 255, 0.06);
      padding: 24px;
      width: 600px;
    }
    label {
      font-size: 14px;
      color: #555;
      font-weight: 600;
      margin-bottom: 6px;
      display: block;
    }
    input[type="text"] {
      width: 100%;
      padding: 12px;
      border: 1px solid #dbdfe7;
      border-radius: 6px;
      margin-bottom: 16px;
      font-size: 14px;
      color: #71747A;
    }
    #editor {
      height: 220px;
      background: #fff;
      border: 1px solid #dbdfe7;
      border-radius: 6px;
      margin-bottom: 16px;
    }
    button {
      background: #e5a552;
      color: #fff;
      font-weight: bold;
      border: none;
      border-radius: 6px;
      padding: 12px 20px;
      cursor: pointer;
      width: 100%;
      height: 48px;
      font-size: 14px;
    }
  </style>
</head>

<body>
  <div class="card">
    <h2 style="color:#525356;margin-bottom:20px;">Editar notícia</h2>

    <form action="https://n8n.ooniverse.ai/webhook/save-news" method="POST">

      <!-- ID oculto -->
      <input type="hidden" name="id" value="${id}">

      <!-- Imagem atual oculta -->
      <input type="hidden" name="imagens" value="${esc(imagens)}">

      <!-- Título -->
      <label>Título da notícia:</label>
      <input type="text" name="titulo" value="${esc(titulo)}">

      <!-- Editor Quill -->
      <label>Texto da notícia:</label>
      <div id="editor"></div>

      <!-- Campo oculto que receberá o HTML -->
      <input type="hidden" name="text" id="texto_html">

      <!-- Imagem atual -->
      <label>Imagem atual:</label>
      <img src="${imagens}" style="max-width:100%;border-radius:6px;margin-bottom:12px;border:1px solid #dbdfe7;">

      <!-- Botão trocar imagem -->
      <a href="https://n8n.ooniverse.ai/form/697ac58a-3b4d-4315-a3f7-7c6ae26b8f80?id=${id}"
         style="display:inline-block;padding:10px 16px;background:#e5a552;color:#fff;border-radius:6px;
                text-decoration:none;font-weight:600;margin-bottom:16px;">
        Trocar imagem
      </a>

      <!-- Vídeo -->
      <label>Link do vídeo (opcional):</label>
      <input type="text" name="video" value="${esc(video)}">

      <button type="submit">Salvar alterações</button>
    </form>
  </div>

  <!-- JS do Quill -->
  <script src="https://cdn.jsdelivr.net/npm/quill@2.0.3/dist/quill.js"></script>

  <script>
    // Inicializa o editor
    const quill = new Quill('#editor', {
      modules: {
        toolbar: [
          [{ header: [1, 2, false] }],
          ['bold', 'italic', 'underline'],
          ['link', 'blockquote', 'code-block'],
          [{ list: 'ordered' }, { list: 'bullet' }]
        ]
      },
      theme: 'snow'
    });

    // Carrega o texto existente
    quill.root.innerHTML = \`${text}\`;

    // Antes de enviar, copia o HTML para o campo oculto
    document.querySelector('form').addEventListener('submit', function () {
      document.getElementById('texto_html').value = quill.root.innerHTML;
    });
  </script>

</body>
</html>
`;

// Retorno final
return [
  {
    json: {
      id,
      titulo,
      text,
      video,
      imagens,
      html
    }
  }
];

const items = $input.all();

return items.map(item => {
  const region = 'us-east-1';
  const bucket = 'auto.1mc.co';
  const folder = 'Kutsaca';

  // pega a primeira chave binária existente
  const binKeys = Object.keys(item.binary || {});
  if (binKeys.length === 0) {
    throw new Error('Nenhum arquivo binário encontrado.');
  }

  const bin = item.binary[binKeys[0]];
  const filename = bin.fileName;

  if (!filename) {
    throw new Error('Nenhum filename encontrado no formulário.');
  }

  const encoded = encodeURIComponent(filename).replace(/%20/g, '+');
  const imageUrl = `https://s3.${region}.amazonaws.com/${bucket}/${folder}/${encoded}`;

  return {
    json: {
      imageUrl,
      filename,
      uploadedAt: new Date().toISOString()
    }
  };
});

const items = $input.all();

return items.map(item => {
  const region = 'us-east-1';
  const bucket = 'auto.1mc.co';
  const folder = 'Kutsaca';

  // pega a primeira chave binária existente
  const binKeys = Object.keys(item.binary || {});
  if (binKeys.length === 0) {
    throw new Error('Nenhum arquivo binário encontrado.');
  }

  const bin = item.binary[binKeys[0]];
  const filename = bin.fileName;

  if (!filename) {
    throw new Error('Nenhum filename encontrado no formulário.');
  }

  const encoded = encodeURIComponent(filename).replace(/%20/g, '+');
  const imageUrl = `https://s3.${region}.amazonaws.com/${bucket}/${folder}/${encoded}`;

  return {
    json: {
      imageUrl,
      filename,
      uploadedAt: new Date().toISOString()
    }
  };
});

return [{
  json: {
    body: $json.body
  }
}];

// Node: Remover bloco de orientações/aprovação do HTML final

const html = $json.html || "";

// Remove tudo a partir de "Orientações para o gestor da newsletter" até o fim
const cleanedHtml = html.replace(
  /Orientações para o gestor da newsletter[\s\S]*$/i,
  ""
);

return [{ json: { html: cleanedHtml } }];

const items = $input.all();

// Lista final de emails
let emails = [];

for (const item of items) {
  const row = item.json;

  // Tenta encontrar o campo de email automaticamente
  const emailField = Object.keys(row).find(k =>
    k.toLowerCase().includes("email")
  );

  if (emailField && row[emailField]) {
    const email = String(row[emailField]).trim();

    // Validação simples
    if (email.includes("@")) {
      emails.push(email);
    }
  }
}

// Remove duplicados
emails = [...new Set(emails)];

// Retorna um único item com os emails formatados
return [
  {
    json: {
      emailsArray: emails,          // array completo
      emailsCSV: emails.join(","),  // string separada por vírgulas
      emails: emails.join(","),     // alias para facilitar no EmailSend
      totalEmails: emails.length
    }
  }
];

// Node: Filtrar até 100 emails e retornar CSV + registros completos + idnews + subject + html

// 1. Pega todos os itens vindos do node anterior
const items = $input.all();

// 2. Recupera dados globais (idnews, subject, html) do primeiro item
const idnews = items[0].json.idnews;
const subject = items[0].json.subject;
const html = items[0].json.html;

// 3. Extrai todos os registros completos
const rows = items.map(i => i.json);

// 4. Extrai apenas os e-mails válidos
const emails = rows
  .map(r => r.Email || r.email || "")
  .map(e => String(e).trim())
  .filter(e => e.includes("@"));

// 5. Limita a 100
const limitados = rows.slice(0, 100);
const emailsLimitados = emails.slice(0, 100);

// 6. Gera CSV
const emailsCSV = emailsLimitados.join(",");

// 7. Retorna:
// - item 0: CSV + idnews + subject + html (para envio)
// - itens 1..100: registros completos (para update)
return [
  {
    json: {
      idnews,
      subject,
      html,
      emailsCSV
    }
  },
  ...limitados.map(r => ({
    json: {
      ...r
    }
  }))
];

// Node: Preparar atualização — marca os registros usados como "news enviada"

// 1. ID da news atual (propagado no fluxo)
const newsAtual = parseInt($json.idnews, 10);

// 2. Pega os registros vindos do node "Filtrar 100"
const rows = $items("Filtrar 100", 0, 0)
  .map(i => i.json)
  .filter(r => r.row_number);

// 3. Retorna cada registro com o campo atualizado
return rows.map(r => ({
  json: {
    row_number: r.row_number,
    "news enviada": newsAtual
  }
}));

